From 7d62502d6c123d08411a0be8a9a38d90861833d8 Mon Sep 17 00:00:00 2001
From: Dan Fandrich <dan@coneharvesters.com>
Date: Thu, 9 Mar 2017 09:06:13 +0100
Subject: [PATCH] polarssl: fixed compile errors introduced in 6448f98c


diff --git a/lib/vtls/polarssl.c b/lib/vtls/polarssl.c
index aa34bbc43..b2fea8a54 100644
--- a/lib/vtls/polarssl.c
+++ b/lib/vtls/polarssl.c
@@ -140,7 +140,7 @@ static void polarssl_debug(void *context, int level, const char *line)
 static Curl_recv polarssl_recv;
 static Curl_send polarssl_send;

-static CURLcode polarssl_version_from_curl(int *polarver, long version)
+static CURLcode polarssl_version_from_curl(int *polarver, long ssl_version)
 {
   switch(ssl_version) {
     case CURL_SSLVERSION_TLSv1_0:
@@ -159,7 +159,7 @@ static CURLcode polarssl_version_from_curl(int *polarver, long version)
 }

 static CURLcode
-set_ssl_version_min_max(struct connectdata *conn, int sockindex);
+set_ssl_version_min_max(struct connectdata *conn, int sockindex)
 {
   struct Curl_easy *data = conn->data;
   struct ssl_connect_data* connssl = &conn->ssl[sockindex];
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was likely caused by mismatched function signatures and parameter names, which can lead to compile errors when the function is called with incorrect arguments or when the function's definition does not match its declaration. This inconsistency can prevent the compiler from correctly linking the function calls to their definitions, resulting in compilation failures.

        Commit message:
        polarssl: fixed compile errors introduced in 6448f98c  

        Patch:

-static CURLcode polarssl_version_from_curl(int *polarver, long version)
+static CURLcode polarssl_version_from_curl(int *polarver, long ssl_version)
 {
   switch(ssl_version) {
     case CURL_SSLVERSION_TLSv1_0:
       *polarver = SSL_MINOR_VERSION_1;
       return CURLE_OK;
     case CURL_SSLVERSION_TLSv1_1:
       *polarver = SSL_MINOR_VERSION_2;
       return CURLE_OK;
     case CURL_SSLVERSION_TLSv1_2:
       *polarver = SSL_MINOR_VERSION_3;
       return CURLE_OK;
     case CURL_SSLVERSION_TLSv1_3:
       break;
   }
   return CURLE_SSL_CONNECT_ERROR;
 }

 static CURLcode
-set_ssl_version_min_max(struct connectdata *conn, int sockindex);
+set_ssl_version_min_max(struct connectdata *conn, int sockindex)
 {
   struct Curl_easy *data = conn->data;
   struct ssl_connect_data* connssl = &conn->ssl[sockindex];
   long ssl_version = SSL_CONN_CONFIG(version);
   long ssl_version_max = SSL_CONN_CONFIG(version_max);
   int ssl_min_ver = SSL_MINOR_VERSION_1;
   int ssl_max_ver = SSL_MINOR_VERSION_1;
   CURLcode result = CURLE_OK;

   switch(ssl_version) {
     case CURL_SSLVERSION_DEFAULT:
     case CURL_SSLVERSION_TLSv1:
       ssl_version = CURL_SSLVERSION_TLSv1_0;
       ssl_version_max = CURL_SSLVERSION_MAX_TLSv1_2;
       break;
   }

   switch(ssl_version_max) {
     case CURL_SSLVERSION_MAX_NONE:
       ssl_version_max = ssl_version << 16;
       break;
     case CURL_SSLVERSION_MAX_DEFAULT:
       ssl_version_max = CURL_SSLVERSION_MAX_TLSv1_2;
       break;
   }

   result = polarssl_version_from_curl(&ssl_min_ver, ssl_version);
   if(result) {
     failf(data, "unsupported min version passed via CURLOPT_SSLVERSION");
     return result;
   }
   result = polarssl_version_from_curl(&ssl_max_ver, ssl_version_max >> 16);
   if(result) {
     failf(data, "unsupported max version passed via CURLOPT_SSLVERSION");
     return result;
   }

   ssl_set_min_version(&connssl->ssl, SSL_MAJOR_VERSION_3, ssl_min_ver);
   ssl_set_max_version(&connssl->ssl, SSL_MAJOR_VERSION_3, ssl_max_ver);

   return result;
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>
